import json
from pathlib import Path
p=Path('Assignment 2/work/ai_screening')
R=json.loads((p/'web_targets_saif.json').read_text())
D={}
# All listed DOI searches were actually run with the web search tool.
for r in R:
 D[r['id']]=dict(id=r['id'],decision='Include',criterion='Potentially eligible; full-text assessment needed',rationale='Advance to full text because complete primary abstract/method evidence was not accessible; an access failure is not an exclusion reason.',search_query='"'+r['doi']+'"',source_url='https://doi.org/'+r['doi'],title_match='Not confirmed from an accessible primary article',evidence_level='Search unsuccessful',evidence_text='No complete primary abstract or relevant article text obtained for an eligibility judgment.',access_note='DOI search attempted; primary DOI/publisher route unavailable. This is a conservative retrieval decision, not evidence that eligibility is established.')
def put(id,decision,criterion,url,level,evidence,why,note='Full abstract inspected; full-paper reading is not claimed.'):
 D[id].update(decision=decision,criterion=criterion,source_url=url,title_match='Exact title and DOI match',evidence_level=level,evidence_text=evidence,rationale=why,access_note=note)
def meta(id,url,evidence,note):
 D[id].update(source_url=url,title_match='Title matched in metadata; primary full abstract not obtained',evidence_level='Metadata only',evidence_text=evidence,access_note=note)
put('N031','Exclude','EC1','https://avesis.uludag.edu.tr/yayin/a9b32afb-3f88-4039-8b4a-26575fc0821f/a-novel-stacking-ensemble-framework-for-predicting-workability-of-cement-superplasticizer-systems-with-shap-and-lime-interpretability','Full abstract','The author university record describes 171 observations, stacking classification, predictive fold consistency, SHAP factor rankings and LIME physical plausibility.','Fold consistency refers to workability prediction; SHAP/LIME explanations are not separately assessed for stability.','Complete author-university abstract read; IEEE DOI route inaccessible.')
put('N046','Exclude','EC1','https://ieeexplore.ieee.org/abstract/document/11021774','Full abstract','The complete cached publisher abstract compares crop classifiers on soil/climate features and uses SHAP/LIME to identify responsible inputs.','The measured outcome is classification performance; no separate explanation-stability assessment is reported.','Complete publisher abstract was returned as cached page content by web search, not a short snippet. Direct page opening hit bot/418 checks; no full text read.')
meta('N052','https://ieeexplore.ieee.org/document/11504054','Exact-title/DOI conference metadata located, but only secondary abstract reproduction was accessible.','Primary IEEE document and abstract routes returned cache misses. The secondary summary was not treated as primary verification; advance to full text.')
put('N071','Exclude','EC1','https://www.researchgate.net/publication/381542146_Enhancing_photovoltaic_system_performance_using_advanced_gradient_boosting_methods','Targeted full text','Author-uploaded paper abstract and framework text evaluate PV forecasts using R²/RMSE/MAE; SHAP identifies solar radiation as the main driver.','Grid stability and forecast reliability are the subject; no separately measured SHAP explanation-stability outcome is described.','Matching author manuscript opened on ResearchGate; page identifies upload by Abdelhakim Dorbane. Abstract and relevant framework passages inspected, not an exhaustive paper audit.')
meta('N083','https://ieeexplore.ieee.org/document/11717313','Exact-title searches found an author-associated university repost confirming a conference presentation; no primary article abstract was accessible.','IEEE unavailable. No full-abstract or paper verification claimed. Include for full-text assessment.')
meta('N091','https://nayebul.com/','The coauthor website lists the matching heart-disease paper and exact DOI.','Author page opened and title/DOI inspected; no article abstract supplied there and IEEE route unavailable. Include for full-text assessment.')
meta('N108','https://ieeexplore.ieee.org/document/11651877','Matching title/DOI and a secondary abstract reproduction found; it mentions SHAP ranking consistency across oversampling strategies.','IEEE opening returned cache miss. No primary abstract confirmed; Include to inspect the potentially relevant ranking-stability outcome in full text.')
