out=[D[r['id']] for r in R]
assert len(out)==36 and len({x['id'] for x in out})==36
assert all(x['decision'] in ['Include','Exclude'] for x in out)
(p/'web_review_saif.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
from collections import Counter
print('Decisions',Counter(x['decision'] for x in out))
print('Evidence',Counter(x['evidence_level'] for x in out))
